mapper.select:


    a.del_flag = '0'

        and a.alert_no like concat('%', #{alertNo}, '%')


        and a.rule_code = #{ruleCode}


        and a.object_type = #{objectType}


        and a.object_name like concat('%', #{objectName}, '%')


        and a.alert_level = #{alertLevel}


        and a.status = #{status}


        and date_format(a.create_time, '%Y%m%d') >= date_format(#{params.beginTime}, '%Y%m%d')


        and date_format(a.create_time, '%Y%m%d') <= date_format(#{params.endTime}, '%Y%m%d')


order by
    case a.alert_level when '2' then 0 when '1' then 1 else 2 end,
    a.score desc,
    a.create_time desc

select count(1) from jc_risk_alert
where del_flag = '0' and rule_id = #{ruleId} and object_type = #{objectType}
  and status in ('0','1')


        and object_id = #{objectId}


        and (object_id is null or object_id = 0) and object_name = #{objectName}

mapper.update:
update jc_risk_alert
status = #{status}, verify_opinion = #{verifyOpinion}, verify_by = #{verifyBy}, verify_time = #{verifyTime}, issue_id = #{issueId}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where alert_id = #{alertId}
